using eWolfBootstrap.Builders;
using eWolfBootstrap.SiteBuilder;
using eWolfBootstrap.SiteBuilder.Attributes;
using eWolfBootstrap.SiteBuilder.Enums;
using eWolfSiteBuilder.Helpers;

namespace eWolfSiteBuilder._Site.Apps.SlideshowVideoCreator
{
    [PageTitle("index.html")]
    public class Index : PageDetailsWolfSite
    {
        private const string HeaderImage = "FeatureGraphic-1024x500.png";
        private const string ImageFolder = "Images";

        /// <summary>
        /// The app's Store page. Replace with the real address from Partner Center
        /// (Product identity → "URL for Windows 10 and later") when it goes live.
        /// </summary>
        private const string StoreLink = "https://apps.microsoft.com/";

        /// <summary>
        /// The app isn't in the Microsoft Store yet, so a store button would lead nowhere.
        /// Flip this to true (and set StoreLink) on the day it goes live; the Apps page, the
        /// heading, the wording and the buttons all follow it.
        /// </summary>
        public static readonly bool Released = false;

        /// <summary>
        /// The same pictures as the Microsoft Store listing. They're taken from the real app by
        /// CreateSlideShow\tools\Take-StoreScreenshots.ps1 and copied into
        /// DemoSite/Apps/SlideshowVideoCreator/Images (not generated by the builder).
        /// </summary>
        private static readonly (string File, string Caption)[] Screenshots = new (string, string)[]
        {
            ("01-photos.png", "Pick a folder and choose your photos"),
            ("02-preview.png", "Preview your video in seconds, title card and all"),
            ("03-making.png", "Smooth pans, transitions, a series title and your music"),
            ("04-title-card.png", "An opening title card for every video"),
            ("05-portrait-crop.png", "Choose how each portrait photo is framed"),
            ("06-settings.png", "Timing, series title, music and video quality"),
        };

        public Index()
        {
            WebPage = new WebPage(this);
            DisplayTitle = "Slideshow Video Creator";
            MenuTitle = "Slideshow Video Creator";
            Keywords.Add(DisplayTitle);
            Keywords.AddRange(
                 new string[]
                 {
                    "slideshow maker",
                    "photo slideshow",
                    "photos to video",
                    "Windows app",
                    "Microsoft Store"
                 });
        }

        /// <summary>The Microsoft Store button, shared with the Apps page.</summary>
        public static string StoreButton()
        {
            return $"<a href='{StoreLink}' target='_blank' class='btn btn-success btn-lg'>Get it from Microsoft</a>";
        }

        public override void CreatePage()
        {
            WebPage.AddHeader(this, string.Empty);
            WebPage.AddNavigation(NavigationTypes.Main, @"../../");
            WebPage.StartBody();

            WebPage.StartDiv("<div class='container mt-12'>");

            WebPage.Append(CreateHero());
            WebPage.Append(CreateDescription());
            WebPage.Append(CreateScreenShots());
            WebPage.Append(CreateRequirements());

            WebPage.CloseAllsDiv();
            WebPage.EndBody();
            WebPage.Output();
        }

        private void AddScreenShot(HTMLSection section, string imageName, string caption)
        {
            section.ImagePath($"{ImageFolder}/{imageName}", 90);
            section.StartTextCenter();
            section.Text(caption);
            section.EndTextCenter();
            section.NewLine();
        }

        private string CreateDescription()
        {
            HTMLBuilder outer = new HTMLBuilder();

            outer.StartTextCenter();
            outer.Text("Pick a folder of photos and Slideshow Video Creator turns it into an MP4 video, ready to play on a TV, share with family or upload to YouTube and Facebook.");
            outer.NewLine();
            outer.NewLine();
            outer.EndTextCenter();

            outer.InspectorDetails("Titles", "An animated opening title card with the place, the date and who was there, plus an optional series title on every photo");
            outer.InspectorDetails("Movement", "Smooth transitions between photos (one style, a mix you choose, or random), and a gentle pan across portrait photos, which you can position yourself");
            outer.InspectorDetails("Your music", "Background music from your own music folder, with volume and fades");
            outer.InspectorDetails("Choosing photos", "Untick the ones you don't want, rotate any photo, and put them in name order, date-taken order or your own order");
            outer.InspectorDetails("Preview", "Watch a short preview of the title card and first photos in seconds, before making the whole video");
            outer.InspectorDetails("Video settings", "720p, 1080p or 4K, at 24 to 60 frames per second");
            outer.InspectorDetails("Big folders", "Hundreds of photos, including OneDrive folders");
            outer.InspectorDetails("Private", $"Everything happens on your PC. Nothing is uploaded, and the app collects no personal data (<a href='{PrivacyPolicy.Page}'>privacy policy</a>)");

            outer.NewLine();
            outer.NewLine();
            outer.StartTextCenter();
            outer.Text(Released
                ? "Slideshow Video Creator is available from the Microsoft Store for Windows 10 and Windows 11."
                : "Slideshow Video Creator is finished and on its way to the Microsoft Store, for Windows 10 and Windows 11.");
            outer.NewLine();
            outer.NewLine();
            if (Released)
            {
                outer.Text(StoreButton());
                outer.NewLine();
                outer.NewLine();
            }
            outer.EndTextCenter();

            return outer.Output();
        }

        private string CreateHero()
        {
            HTMLBuilder outer = new HTMLBuilder();

            outer.ImagePath($"{ImageFolder}/{HeaderImage}", 100);
            outer.NewLine();
            outer.Jumbotron(DisplayTitle, Released
                ? "Turn a folder of photos into a finished slideshow video, with titles, transitions and music, in a few clicks. Out now for Windows."
                : "Turn a folder of photos into a finished slideshow video, with titles, transitions and music, in a few clicks. Coming soon to the Microsoft Store.");

            if (Released)
            {
                outer.StartTextCenter();
                outer.Text(StoreButton());
                outer.NewLine();
                outer.EndTextCenter();
            }

            return outer.Output();
        }

        private string CreateRequirements()
        {
            HTMLBuilder outer = new HTMLBuilder();

            outer.StartTextCenter();
            outer.Text("<h3>Requirements</h3>");
            outer.NewLine();
            outer.EndTextCenter();

            outer.InspectorDetails("Windows", "Windows 10 (version 2004 or later) or Windows 11, 64-bit");
            outer.InspectorDetails("iPhone photos (HEIC)", "Need Microsoft's HEVC Video Extensions (a small paid add-on from the Microsoft Store) and the free HEIF Image Extension. JPEG, PNG and most other photos need nothing extra");
            outer.InspectorDetails("Windows \"N\" editions", "Need Microsoft's free Media Feature Pack before videos can be made. The app checks and explains");

            outer.NewLine();
            outer.StartTextCenter();
            outer.Text($"Questions? See <a href='{Support.Page}'>help &amp; support</a>, or email Contact@electricWolf.co.uk");
            outer.NewLine();
            outer.NewLine();
            outer.Text($"<a href='{Support.Page}'>Help &amp; support</a>&nbsp;&nbsp;·&nbsp;&nbsp;<a href='{PrivacyPolicy.Page}'>Privacy policy</a>");
            outer.NewLine();
            outer.EndTextCenter();

            return outer.Output();
        }

        private string CreateScreenShots()
        {
            HTMLBuilder outer = new HTMLBuilder();

            outer.StartTextCenter();
            outer.Text("<h3>Screen shots</h3>");
            outer.NewLine();
            outer.EndTextCenter();

            for (int row = 0; row < Screenshots.Length; row += 3)
            {
                HTMLBuilder options = new HTMLBuilder();
                HTMLSection a = new HTMLSection("col-md-4");
                HTMLSection b = new HTMLSection("col-md-4");
                HTMLSection c = new HTMLSection("col-md-4");
                options.SetThreeSections(a, b, c);

                HTMLSection[] sections = { a, b, c };
                for (int i = 0; i < 3 && row + i < Screenshots.Length; i++)
                    AddScreenShot(sections[i], Screenshots[row + i].File, Screenshots[row + i].Caption);

                outer.Text(options.Output());
                outer.NewLine();
            }

            return outer.Output();
        }
    }
}
